				// 筛选后的图标
				filteredIcons: [],
				// 每次加载的数量
				batchSize: 20,
				// 当前已加载的数量
				loadedCount: 0,
				// 是否正在加载
				isLoading: false,
				// 用于防抖的计时器
				searchTimer: null
			};
		},
		computed: {
			// 可见的图标（已加载的部分）
			visibleIcons() {
				return this.filteredIcons.slice(0, this.loadedCount);
			},
			// 筛选后的总数
			totalFilteredCount() {
				return this.filteredIcons.length;
			}
		},
		mounted() {
			// 初始化筛选
			this.filteredIcons = [...this.allIcons];
			// 初始加载
			this.loadMore();

			// 监听滚动事件
			window.addEventListener('scroll', this.handleScroll);
		},
		beforeUnmount() {
			// 移除滚动监听
			window.removeEventListener('scroll', this.handleScroll);
		},
		methods: {
			// 处理搜索
			handleSearch() {
				const query = this.searchQuery.toLowerCase().trim();

				if (!query) {
					this.filteredIcons = [...this.allIcons];
				} else {
					this.filteredIcons = this.allIcons.filter(icon =>
						icon.name.toLowerCase().includes(query) ||
						(icon.cnName && icon.cnName.toLowerCase().includes(query))
					);
				}

				// 重置加载状态
				this.loadedCount = 0;
				this.loadMore();

			},

			// 加载更多图标
			loadMore() {
				if (this.isLoading || this.loadedCount >= this.totalFilteredCount) {
					return;
				}

				this.isLoading = true;

				// 模拟网络请求延迟
				setTimeout(() => {
					// 计算本次加载的数量
					const newCount = Math.min(
						this.loadedCount + this.batchSize,
						this.totalFilteredCount
					);

					this.loadedCount = newCount;
					this.isLoading = false;
				}, 500);
			},

			// 处理滚动事件
			handleScroll() {
				// 当滚动到页面底部附近时加载更多
				if (
					window.innerHeight + window.scrollY >=
					document.body.offsetHeight - 500 && // 距离底部500px时触发
					!this.isLoading &&
					this.loadedCount < this.totalFilteredCount
				) {
					this.loadMore();
				}
			},

			// 处理图标点击
			handleIconClick(icon) {
				this.selectedIcon = icon;
			},

			// 复制图标路径
			copyIconPath(icon) {
				const iconPath = `${icon.name}`;
				navigator.clipboard.writeText(iconPath).then(() => {
					this.selectedIcon = null
				 	this.$api.msg('图标名称已复制到剪贴板');
				}).catch(err => {
					console.error('无法复制名称: ', err);
						this.$model.showToast('复制失败，请手动复制');
				});
			}
		}
	};
